/**
 * wrangler.toml for a project's two comms Workers, from its comms config:
 *   <project>-comms-engine  — D1 (and optional KV) bindings, the MAIL_SENDER Service binding
 *   <project>-mail-sender   — the send_email binding, restricted to the config's sender address
 */
import { resolveConfig } from "./config.js";

const q = (v) => JSON.stringify(String(v));
const workerNamePrefix = (r) => r.workers?.namePrefix || r.project;

/** { name, logPrefix } for createMailSender. */
export function mailSenderOptions(config) {
  const r = resolveConfig(config);
  return { name: `${workerNamePrefix(r)}-mail-sender`, logPrefix: `${r.idPrefix}-mail-sender` };
}

/** The wrangler.toml text of one comms Worker: kind is "comms-engine" or "mail-sender". */
export function wranglerToml(config, kind) {
  const r = resolveConfig(config);
  const w = r.workers || {};
  const name = r.domain;
  const L = [];
  if (kind === "comms-engine") {
    const e = w.engine || {};
    L.push(
      `# ${name} Comms Engine — generated by @saasreport/comms from the project's comms config; edit the config, not this file.`,
      "# SINGLE dispatch point for every",
      "# outbound email. No public route: reached only via Service binding (COMMS) from the site Worker.",
      "",
      `name = ${q(`${workerNamePrefix(r)}-comms-engine`)}`,
      `main = ${q(e.main || "src/index.js")}`,
      `compatibility_date = ${q(e.compatibilityDate || "2026-05-19")}`,
      "workers_dev = false",
      "preview_urls = false",
    );
    const vars = { COMMS_ENGINE_VERSION: r.manifest.version, CONSTITUTION_REF: r.manifest.constitutionRef, ...(e.vars || {}) };
    L.push("", "[vars]", ...Object.entries(vars).map(([k, v]) => `${k} = ${q(v)}`));
    if (e.d1) {
      L.push("", "[[d1_databases]]", `binding = ${q(e.d1.binding || "DB")}`, `database_name = ${q(e.d1.database_name)}`, `database_id = ${q(e.d1.database_id)}`);
      if (e.d1.migrations_dir) L.push(`migrations_dir = ${q(e.d1.migrations_dir)}`);
    }
    for (const kv of e.kv || []) L.push("", "[[kv_namespaces]]", `binding = ${q(kv.binding)}`, `id = ${q(kv.id)}`);
    L.push("", "[[services]]", 'binding = "MAIL_SENDER"', `service = ${q(`${workerNamePrefix(r)}-mail-sender`)}`);
    if (e.observability !== false) L.push("", "[observability]", "enabled = true");
  } else if (kind === "mail-sender") {
    const m = w.mailSender || {};
    const domain = r.sender.address.split("@")[1];
    L.push(
      `# ${name} Mail Sender — generated by @saasreport/comms from the project's comms config; edit the config, not this file.`,
      "# Outbound primitive on Cloudflare Email Sending: the ONLY Worker that touches the send_email binding.",
      "# Reached exclusively via Service binding from the Comms Engine; no public route.",
      `# Sending domain: ${domain} (Cloudflare Email Service; its DNS records are set up once, outside the kit).`,
      "",
      `name = ${q(`${workerNamePrefix(r)}-mail-sender`)}`,
      `main = ${q(m.main || "src/index.js")}`,
      `compatibility_date = ${q(m.compatibilityDate || "2026-05-05")}`,
      "workers_dev = false",
      "preview_urls = false",
      "",
      "[[send_email]]",
      'name = "MAIL"',
      "remote = true",
      `allowed_sender_addresses = [${[r.sender.address, ...(r.sender.alsoAllowed || [])].map(q).join(", ")}]`,
    );
  } else throw new Error(`wranglerToml: kind must be "comms-engine" or "mail-sender", got ${kind}`);
  return L.join("\n") + "\n";
}
